export function encodePose(m: Pose): Uint8Array {
	const w = new WireWriter();
	writePose(w, m);
	return w.finish();
}

export function decodePose(b: Uint8Array): Pose {
	return readPose(new WireReader(b));
}

function writePose(w: WireWriter, m: Pose): void {
	if (m.x !== 0 || Object.is(m.x, -0)) {
		w.tag(1, 1);
		w.double(m.x);
	}
	if (m.y !== 0 || Object.is(m.y, -0)) {
		w.tag(2, 1);
		w.double(m.y);
	}
	if (m.z !== 0 || Object.is(m.z, -0)) {
		w.tag(3, 1);
		w.double(m.z);
	}
	if (m.yaw !== 0 || Object.is(m.yaw, -0)) {
		w.tag(4, 1);
		w.double(m.yaw);
	}
}

function readPose(r: WireReader): Pose {
	const m = newPose();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 1) m.x = r.double();
				else r.skip(wireType, field);
				break;
			case 2:
				if (wireType === 1) m.y = r.double();
				else r.skip(wireType, field);
				break;
			case 3:
				if (wireType === 1) m.z = r.double();
				else r.skip(wireType, field);
				break;
			case 4:
				if (wireType === 1) m.yaw = r.double();
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

