/**
 * Play is the printed part of a card or a power.
 */
export interface Play {
	key: string;
	name: string;
	kind: AbilityKind;
	skill: Skill;
	ap: number;
	mod: number;
	noise: number;
	/**
	 * Absent means the card has no printed DC, which is not DC 0.
	 */
	dc?: number;
	targets: string[];
	on: Owner[];
	effect: Effect;
	wide: boolean;
	dormant: boolean;
	foothold: FootholdKind;
	evicts: boolean;
	text: string;
}

export function newPlay(init: Partial<Play> = {}): Play {
	return {
		key: '',
		name: '',
		kind: 'unspecified',
		skill: 'unspecified',
		ap: 0,
		mod: 0,
		noise: 0,
		targets: [],
		on: [],
		effect: 'unspecified',
		wide: false,
		dormant: false,
		foothold: 'unspecified',
		evicts: false,
		text: '',
		...init
	};
}

export function encodePlay(m: Play): Uint8Array {
	const w = new WireWriter();
	writePlay(w, m);
	return w.finish();
}

export function decodePlay(b: Uint8Array): Play {
	return readPlay(new WireReader(b));
}

function writePlay(w: WireWriter, m: Play): void {
	if (m.key.length > 0) {
		w.tag(1, 2);
		w.string(m.key);
	}
	if (m.name.length > 0) {
		w.tag(2, 2);
		w.string(m.name);
	}
	if (AbilityKindToWire[m.kind] !== 0) {
		w.tag(3, 0);
		w.int(AbilityKindToWire[m.kind]);
	}
	if (SkillToWire[m.skill] !== 0) {
		w.tag(4, 0);
		w.int(SkillToWire[m.skill]);
	}
	if (m.ap !== 0) {
		w.tag(5, 0);
		w.int(m.ap);
	}
	if (m.mod !== 0) {
		w.tag(6, 0);
		w.int(m.mod);
	}
	if (m.noise !== 0) {
		w.tag(7, 0);
		w.int(m.noise);
	}
	if (m.dc !== undefined) {
		const v = m.dc;
		w.tag(8, 0);
		w.int(v);
	}
	for (const v of m.targets) {
		w.tag(9, 2);
		w.string(v);
	}
	if (m.on.length > 0) {
		w.sub(10, (c) => {
			for (const v of m.on) {
				c.int(OwnerToWire[v]);
			}
		});
	}
	if (EffectToWire[m.effect] !== 0) {
		w.tag(11, 0);
		w.int(EffectToWire[m.effect]);
	}
	if (m.wide) {
		w.tag(12, 0);
		w.bool(m.wide);
	}
	if (m.dormant) {
		w.tag(13, 0);
		w.bool(m.dormant);
	}
	if (FootholdKindToWire[m.foothold] !== 0) {
		w.tag(14, 0);
		w.int(FootholdKindToWire[m.foothold]);
	}
	if (m.evicts) {
		w.tag(15, 0);
		w.bool(m.evicts);
	}
	if (m.text.length > 0) {
		w.tag(16, 2);
		w.string(m.text);
	}
}

function readPlay(r: WireReader): Play {
	const m = newPlay();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 2) m.key = r.string();
				else r.skip(wireType, field);
				break;
			case 2:
				if (wireType === 2) m.name = r.string();
				else r.skip(wireType, field);
				break;
			case 3:
				if (wireType === 0) m.kind = AbilityKindFromWire(r.int32());
				else r.skip(wireType, field);
				break;
			case 4:
				if (wireType === 0) m.skill = SkillFromWire(r.int32());
				else r.skip(wireType, field);
				break;
			case 5:
				if (wireType === 0) m.ap = r.int32();
				else r.skip(wireType, field);
				break;
			case 6:
				if (wireType === 0) m.mod = r.int32();
				else r.skip(wireType, field);
				break;
			case 7:
				if (wireType === 0) m.noise = r.int32();
				else r.skip(wireType, field);
				break;
			case 8:
				if (wireType === 0) m.dc = r.int32();
				else r.skip(wireType, field);
				break;
			case 9:
				if (wireType === 2) m.targets.push(r.string());
				else r.skip(wireType, field);
				break;
			case 10:
				if (wireType === 2) {
					const pr = r.sub();
					while (!pr.done) m.on.push(OwnerFromWire(pr.int32()));
				} else if (wireType === 0) {
					m.on.push(OwnerFromWire(r.int32()));
				} else {
					r.skip(wireType, field);
				}
				break;
			case 11:
				if (wireType === 0) m.effect = EffectFromWire(r.int32());
				else r.skip(wireType, field);
				break;
			case 12:
				if (wireType === 0) m.wide = r.bool();
				else r.skip(wireType, field);
				break;
			case 13:
				if (wireType === 0) m.dormant = r.bool();
				else r.skip(wireType, field);
				break;
			case 14:
				if (wireType === 0) m.foothold = FootholdKindFromWire(r.int32());
				else r.skip(wireType, field);
				break;
			case 15:
				if (wireType === 0) m.evicts = r.bool();
				else r.skip(wireType, field);
				break;
			case 16:
				if (wireType === 2) m.text = r.string();
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

export interface Power {
	play?: Play;
	uses: number;
	cooldown: number;
}

export function newPower(init: Partial<Power> = {}): Power {
	return {
		uses: 0,
		cooldown: 0,
		...init
	};
}

export function encodePower(m: Power): Uint8Array {
	const w = new WireWriter();
	writePower(w, m);
	return w.finish();
}

export function decodePower(b: Uint8Array): Power {
	return readPower(new WireReader(b));
}

function writePower(w: WireWriter, m: Power): void {
	if (m.play !== undefined) {
		const v = m.play;
		w.sub(1, (c) => writePlay(c, v));
	}
	if (m.uses !== 0) {
		w.tag(2, 0);
		w.int(m.uses);
	}
	if (m.cooldown !== 0) {
		w.tag(3, 0);
		w.int(m.cooldown);
	}
}

function readPower(r: WireReader): Power {
	const m = newPower();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 2) m.play = readPlay(r.sub());
				else r.skip(wireType, field);
				break;
			case 2:
				if (wireType === 0) m.uses = r.int32();
				else r.skip(wireType, field);
				break;
			case 3:
				if (wireType === 0) m.cooldown = r.int32();
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

export interface Klass {
	key: string;
	seat: string;
	name: string;
	faction: Faction;
	color: string;
	icon: string;
	resource: string;
	skills: Record<string, number>;
	tagline: string;
	passive?: Passive;
	shape: string;
	power?: Power;
}

export function newKlass(init: Partial<Klass> = {}): Klass {
	return {
		key: '',
		seat: '',
		name: '',
		faction: 'unspecified',
		color: '',
		icon: '',
		resource: '',
		skills: {},
		tagline: '',
		shape: '',
		...init
	};
}

export function encodeKlass(m: Klass): Uint8Array {
	const w = new WireWriter();
	writeKlass(w, m);
	return w.finish();
}

export function decodeKlass(b: Uint8Array): Klass {
	return readKlass(new WireReader(b));
}

function writeKlass(w: WireWriter, m: Klass): void {
	if (m.key.length > 0) {
		w.tag(1, 2);
		w.string(m.key);
	}
	if (m.seat.length > 0) {
		w.tag(2, 2);
		w.string(m.seat);
	}
	if (m.name.length > 0) {
		w.tag(3, 2);
		w.string(m.name);
	}
	if (FactionToWire[m.faction] !== 0) {
		w.tag(4, 0);
		w.int(FactionToWire[m.faction]);
	}
	if (m.color.length > 0) {
		w.tag(5, 2);
		w.string(m.color);
	}
	if (m.icon.length > 0) {
		w.tag(6, 2);
		w.string(m.icon);
	}
	if (m.resource.length > 0) {
		w.tag(7, 2);
		w.string(m.resource);
	}
	for (const k of Object.keys(m.skills).sort()) {
		const v = m.skills[k];
		w.sub(8, (c) => {
			c.tag(1, 2);
			c.string(k);
			c.tag(2, 0);
			c.int(v);
		});
	}
	if (m.tagline.length > 0) {
		w.tag(9, 2);
		w.string(m.tagline);
	}
	if (m.passive !== undefined) {
		const v = m.passive;
		w.sub(10, (c) => writePassive(c, v));
	}
	if (m.shape.length > 0) {
		w.tag(11, 2);
		w.string(m.shape);
	}
	if (m.power !== undefined) {
		const v = m.power;
		w.sub(12, (c) => writePower(c, v));
	}
}

function readKlass(r: WireReader): Klass {
	const m = newKlass();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 2) m.key = r.string();
				else r.skip(wireType, field);
				break;
			case 2:
				if (wireType === 2) m.seat = r.string();
				else r.skip(wireType, field);
				break;
			case 3:
				if (wireType === 2) m.name = r.string();
				else r.skip(wireType, field);
				break;
			case 4:
				if (wireType === 0) m.faction = FactionFromWire(r.int32());
				else r.skip(wireType, field);
				break;
			case 5:
				if (wireType === 2) m.color = r.string();
				else r.skip(wireType, field);
				break;
			case 6:
				if (wireType === 2) m.icon = r.string();
				else r.skip(wireType, field);
				break;
			case 7:
				if (wireType === 2) m.resource = r.string();
				else r.skip(wireType, field);
				break;
			case 8:
				if (wireType !== 2) {
					r.skip(wireType, field);
					break;
				}
				{
					const er = r.sub();
					let k = '';
					let v: number = 0;
					while (!er.done) {
						const [ef, et] = er.tag();
						if (ef === 1 && et === 2) k = er.string();
						else if (ef === 2 && et === 0) v = er.int32();
						else er.skip(et, ef);
					}
					m.skills[k] = v;
				}
				break;
			case 9:
				if (wireType === 2) m.tagline = r.string();
				else r.skip(wireType, field);
				break;
			case 10:
				if (wireType === 2) m.passive = readPassive(r.sub());
				else r.skip(wireType, field);
				break;
			case 11:
				if (wireType === 2) m.shape = r.string();
				else r.skip(wireType, field);
				break;
			case 12:
				if (wireType === 2) m.power = readPower(r.sub());
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

/**
 * CardView is one card in hand, priced for the seat holding it.
 */
export interface CardView {
	play?: Play;
	owner: string;
	copies: number;
	playable: boolean;
	/**
	 * sites are where it may legally be played right now, computed server-side.
	 */
	sites: string[];
	uid: string;
}

export function newCardView(init: Partial<CardView> = {}): CardView {
	return {
		owner: '',
		copies: 0,
		playable: false,
		sites: [],
		uid: '',
		...init
	};
}

export function encodeCardView(m: CardView): Uint8Array {
	const w = new WireWriter();
	writeCardView(w, m);
	return w.finish();
}

export function decodeCardView(b: Uint8Array): CardView {
	return readCardView(new WireReader(b));
}

function writeCardView(w: WireWriter, m: CardView): void {
	if (m.play !== undefined) {
		const v = m.play;
		w.sub(1, (c) => writePlay(c, v));
	}
	if (m.owner.length > 0) {
		w.tag(2, 2);
		w.string(m.owner);
	}
	if (m.copies !== 0) {
		w.tag(3, 0);
		w.int(m.copies);
	}
	if (m.playable) {
		w.tag(4, 0);
		w.bool(m.playable);
	}
	for (const v of m.sites) {
		w.tag(5, 2);
		w.string(v);
	}
	if (m.uid.length > 0) {
		w.tag(6, 2);
		w.string(m.uid);
	}
}

function readCardView(r: WireReader): CardView {
	const m = newCardView();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 2) m.play = readPlay(r.sub());
				else r.skip(wireType, field);
				break;
			case 2:
				if (wireType === 2) m.owner = r.string();
				else r.skip(wireType, field);
				break;
			case 3:
				if (wireType === 0) m.copies = r.int32();
				else r.skip(wireType, field);
				break;
			case 4:
				if (wireType === 0) m.playable = r.bool();
				else r.skip(wireType, field);
				break;
			case 5:
				if (wireType === 2) m.sites.push(r.string());
				else r.skip(wireType, field);
				break;
			case 6:
				if (wireType === 2) m.uid = r.string();
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

export interface CardList {
	cards: CardView[];
}

export function newCardList(init: Partial<CardList> = {}): CardList {
	return {
		cards: [],
		...init
	};
}

export function encodeCardList(m: CardList): Uint8Array {
	const w = new WireWriter();
	writeCardList(w, m);
	return w.finish();
}

export function decodeCardList(b: Uint8Array): CardList {
	return readCardList(new WireReader(b));
}

function writeCardList(w: WireWriter, m: CardList): void {
	for (const v of m.cards) {
		w.sub(1, (c) => writeCardView(c, v));
	}
}

function readCardList(r: WireReader): CardList {
	const m = newCardList();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 2) m.cards.push(readCardView(r.sub()));
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

