/**
 * ReactionFrame is server → client: something this player perceived. Sent to
 * the reaction's audience and nobody else; it never says who caused it.
 */
export interface ReactionFrame {
	tableId: string;
	id: number;
	key: string;
	kind: string;
	zone: string;
	station: string;
	atUnixMs: number;
	/**
	 * badge is the seat a badge-log row names: the badge's owner, not
	 * necessarily who swiped it.
	 */
	badge: string;
	/**
	 * cue is the key of the lighting cue the server sends this seat with the
	 * reaction (office.yaml `cues`); empty for none.
	 */
	cue: string;
}

export function newReactionFrame(init: Partial<ReactionFrame> = {}): ReactionFrame {
	return {
		tableId: '',
		id: 0,
		key: '',
		kind: '',
		zone: '',
		station: '',
		atUnixMs: 0,
		badge: '',
		cue: '',
		...init
	};
}

export function encodeReactionFrame(m: ReactionFrame): Uint8Array {
	const w = new WireWriter();
	writeReactionFrame(w, m);
	return w.finish();
}

export function decodeReactionFrame(b: Uint8Array): ReactionFrame {
	return readReactionFrame(new WireReader(b));
}

function writeReactionFrame(w: WireWriter, m: ReactionFrame): void {
	if (m.tableId.length > 0) {
		w.tag(1, 2);
		w.string(m.tableId);
	}
	if (m.id !== 0) {
		w.tag(2, 0);
		w.varint(m.id);
	}
	if (m.key.length > 0) {
		w.tag(3, 2);
		w.string(m.key);
	}
	if (m.kind.length > 0) {
		w.tag(4, 2);
		w.string(m.kind);
	}
	if (m.zone.length > 0) {
		w.tag(5, 2);
		w.string(m.zone);
	}
	if (m.station.length > 0) {
		w.tag(6, 2);
		w.string(m.station);
	}
	if (m.atUnixMs !== 0) {
		w.tag(7, 0);
		w.int(m.atUnixMs);
	}
	if (m.badge.length > 0) {
		w.tag(8, 2);
		w.string(m.badge);
	}
	if (m.cue.length > 0) {
		w.tag(9, 2);
		w.string(m.cue);
	}
}

function readReactionFrame(r: WireReader): ReactionFrame {
	const m = newReactionFrame();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 2) m.tableId = r.string();
				else r.skip(wireType, field);
				break;
			case 2:
				if (wireType === 0) m.id = r.uint64();
				else r.skip(wireType, field);
				break;
			case 3:
				if (wireType === 2) m.key = r.string();
				else r.skip(wireType, field);
				break;
			case 4:
				if (wireType === 2) m.kind = r.string();
				else r.skip(wireType, field);
				break;
			case 5:
				if (wireType === 2) m.zone = r.string();
				else r.skip(wireType, field);
				break;
			case 6:
				if (wireType === 2) m.station = r.string();
				else r.skip(wireType, field);
				break;
			case 7:
				if (wireType === 0) m.atUnixMs = r.int64();
				else r.skip(wireType, field);
				break;
			case 8:
				if (wireType === 2) m.badge = r.string();
				else r.skip(wireType, field);
				break;
			case 9:
				if (wireType === 2) m.cue = r.string();
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

