export interface TablesFrame {
	tables: TableSummary[];
}

export function newTablesFrame(init: Partial<TablesFrame> = {}): TablesFrame {
	return {
		tables: [],
		...init
	};
}

export function encodeTablesFrame(m: TablesFrame): Uint8Array {
	const w = new WireWriter();
	writeTablesFrame(w, m);
	return w.finish();
}

export function decodeTablesFrame(b: Uint8Array): TablesFrame {
	return readTablesFrame(new WireReader(b));
}

function writeTablesFrame(w: WireWriter, m: TablesFrame): void {
	for (const v of m.tables) {
		w.sub(1, (c) => writeTableSummary(c, v));
	}
}

function readTablesFrame(r: WireReader): TablesFrame {
	const m = newTablesFrame();
	while (!r.done) {
		const [field, wireType] = r.tag();
		switch (field) {
			case 1:
				if (wireType === 2) m.tables.push(readTableSummary(r.sub()));
				else r.skip(wireType, field);
				break;
			default:
				r.skip(wireType, field);
		}
	}
	return m;
}

